-- String, numeric, date and misc function calls plus assorted statements
SELECT UPPER(name), LOWER(name), TRIM(name), LTRIM(name), RTRIM(name), LENGTH(name), CHAR_LENGTH(name), REVERSE(name), REPEAT('ab', 3), LPAD(id, 8, '0'), RPAD(name, 10, '.') FROM t;
SELECT TRIM(BOTH 'x' FROM name), TRIM(LEADING '0' FROM code), TRIM(TRAILING FROM s) FROM t;
SELECT SUBSTRING(name, 2, 3), SUBSTRING(name FROM 2 FOR 3), LEFT(name, 2), RIGHT(name, 2), LOCATE('a', name), INSTR(name, 'a'), REPLACE(name, 'a', 'b') FROM t;
SELECT ABS(x), CEIL(x), FLOOR(x), ROUND(x, 2), TRUNCATE(x, 1), POW(x, 2), SQRT(x), MOD(x, 3), GREATEST(a, b, c), LEAST(a, b, c), SIGN(x) FROM t;
SELECT NOW(), CURDATE(), CURTIME(), CURRENT_TIMESTAMP, CURRENT_DATE, UTC_TIMESTAMP(), SYSDATE(), LOCALTIME;
SELECT CURRENT_TIMESTAMP(6), NOW(3);
SELECT DAYOFWEEK(d), DAYNAME(d), MONTHNAME(d), WEEK(d), WEEKDAY(d), QUARTER(d), LAST_DAY(d), HOUR(t), MINUTE(t), SECOND(t) FROM t;
SELECT DATE_FORMAT(NOW(), '%W, %M %e, %Y %H:%i:%s'), TIME_FORMAT(t, '%h:%i %p');
SELECT DATE_ADD(d, INTERVAL 1 DAY), DATE_SUB(d, INTERVAL 2 WEEK), d + INTERVAL 3 HOUR, d - INTERVAL '1:30' HOUR_MINUTE, ADDDATE(d, 7), SUBDATE(d, INTERVAL 1 YEAR) FROM t;
SELECT TIMESTAMPADD(MINUTE, 30, ts), TIMESTAMPDIFF(SECOND, a, b), PERIOD_DIFF(202401, 202312), SEC_TO_TIME(3600), TIME_TO_SEC('01:00:00') FROM t;
SELECT MD5(x), SHA1(x), SHA2(x, 256), HEX(x), UNHEX(h), TO_BASE64(x), FROM_BASE64(y), CRC32(x), AES_ENCRYPT(x, 'k'), INET_ATON(ip), INET_NTOA(n) FROM t;
SELECT IFNULL(a, 0), NULLIF(a, 0), ISNULL(a), IF(a, 1, 2), COALESCE(a, b) FROM t;
SELECT DATABASE(), USER(), CURRENT_USER(), VERSION(), CONNECTION_ID(), ROW_COUNT(), SCHEMA();
SELECT BENCHMARK(1000, MD5('x')), SLEEP(0);
SELECT JSON_LENGTH(j), JSON_TYPE(j), JSON_VALID(j), JSON_KEYS(j), JSON_SEARCH(j, 'one', 'x'), JSON_MERGE_PATCH(a, b), JSON_REMOVE(j, '$.a'), JSON_ARRAY(1, 2, 3), JSON_INSERT(j, '$.b', 1) FROM t;
SELECT j->'$.a[0]', j->>'$.b.c', j -> '$**.id' FROM t;
SELECT ST_AsText(ST_GeomFromText('POINT(1 1)')), ST_Distance_Sphere(p1, p2) FROM places;
SELECT a FROM t WHERE MATCH(a) AGAINST ('x');
SELECT id FROM t WHERE ts > '2024-01-01' - INTERVAL 1 DAY;
SELECT CAST('2024-01-01' AS DATE), CAST(1 AS SIGNED INTEGER), CAST(x AS CHAR(10)), CAST(x AS DATETIME), CAST(x AS BINARY), CAST(x AS DOUBLE);
SELECT CONVERT(x, SIGNED), CONVERT(x, CHAR);
SELECT DEFAULT(col) FROM t;
SELECT ROW(1, 2) = ROW(1, 2);
SELECT 'a' 'b';
SELECT 1 AS `select`, 2 AS `from`;
SELECT `order`, `group`, `key` FROM `index`;
SELECT TRUE, FALSE, NULL;
SELECT x IS TRUE, x IS NOT FALSE, x IS UNKNOWN FROM t;
SELECT NOW() - INTERVAL 1 DAY, NOW() + INTERVAL '1' DAY;
SELECT 1; SELECT 2;
